async function run(name, event, expectHit) {
  await handler(event);
  const inj = event.context && event.context.inject;
  const got = Array.isArray(inj) && inj.length > 0;
  const txt = got ? inj[0].content.split('\n').filter(l=>l.startsWith('•')).length : 0;
  const ok = (got === expectHit);
  console.log(`${ok?'✅':'🔴'} ${name} → ${got?`注入(${txt}條守則)`:'無注入'}`);
  if (got) inj.forEach(i => i.content.split('\n').filter(l=>l.startsWith('•')).forEach(l=>console.log('     '+l)));
}

